use std::fs::File;
use std::io::{self, Read};
use std::sync::Mutex;

fn load(path: &str, m: &Mutex<()>) -> io::Result<usize> {
    let mut f = File::open(path)?;          // error: return, nothing to undo
    let mut buf = vec![0u8; 4096];
    let _guard = m.lock().unwrap();         // unlocks when _guard is dropped
    let n = f.read(&mut buf)?;              // error: drops _guard, buf, f
    if n < 16 {
        return Err(io::Error::other("short file")); // same cleanup, for free
    }
    // ... parse buf while holding the lock ...
    Ok(n)
}   // normal exit: _guard, buf, f dropped in reverse order of declaration

fn main() {
    let m = Mutex::new(());
    println!("{:?}", load("load.rs", &m).is_ok());       // true
    println!("{:?}", load("/nonexistent", &m).is_err()); // true
    println!("{:?}", m.try_lock().is_ok());               // true: lock released
}

