use std::alloc::{self, Layout};
use std::ptr::{self, NonNull};

// Invariants (all unsafe code below relies on them):
// 1. ptr is valid for cap elements of T (dangling when cap == 0).
// 2. The first len slots are initialized; slots len..cap are not.
// 3. len <= cap. Fields are private: only this module can break 1 to 3.
pub struct MyVec<T> {
    ptr: NonNull<T>,
    cap: usize,
    len: usize,
}

impl<T> MyVec<T> {
    pub fn new() -> Self {
        assert!(std::mem::size_of::<T>() != 0, "no zero-sized types");
        MyVec { ptr: NonNull::dangling(), cap: 0, len: 0 }
    }

    fn grow(&mut self) {
        let new_cap = if self.cap == 0 { 1 } else { 2 * self.cap };
        let new_layout = Layout::array::<T>(new_cap).expect("too large");
        let new_ptr = if self.cap == 0 {
            // SAFETY: new_layout has non-zero size (T is not zero-sized).
            unsafe { alloc::alloc(new_layout) }
        } else {
            let old_layout = Layout::array::<T>(self.cap).unwrap();
            // SAFETY: ptr came from alloc with old_layout (invariant 1).
            unsafe { alloc::realloc(self.ptr.as_ptr() as *mut u8,
                                    old_layout, new_layout.size()) }
        };
        self.ptr = match NonNull::new(new_ptr as *mut T) {
            Some(p) => p,
            None => alloc::handle_alloc_error(new_layout), // abort on OOM
        };
        self.cap = new_cap;
    }

    pub fn push(&mut self, value: T) {
        if self.len == self.cap { self.grow(); }
        // SAFETY: len < cap now, so slot len is inside the allocation
        // (invariant 1) and uninitialized (invariant 2): write, do not assign.
        unsafe { self.ptr.as_ptr().add(self.len).write(value); }
        self.len += 1;
    }

    pub fn pop(&mut self) -> Option<T> {
        if self.len == 0 { return None; }
        self.len -= 1;
        // SAFETY: slot len was initialized (invariant 2); once read, it
        // counts as uninitialized because len no longer covers it.
        unsafe { Some(ptr::read(self.ptr.as_ptr().add(self.len))) }
    }
}

impl<T> Drop for MyVec<T> {
    fn drop(&mut self) {
        while let Some(_) = self.pop() {} // drop every live element first
        if self.cap != 0 {
            let layout = Layout::array::<T>(self.cap).unwrap();
            // SAFETY: same pointer and same layout that alloc/realloc used.
            unsafe { alloc::dealloc(self.ptr.as_ptr() as *mut u8, layout); }
        }
    }
}

pub fn push(&mut self, value: T) {
    if self.len == self.cap { self.grow(); }
    unsafe { self.ptr.as_ptr().add(self.len).write(value); }
    self.len += 1;
}

fn drop(&mut self) {
    while let Some(_) = self.pop() {}
    if self.cap != 0 { /* dealloc with the same Layout */ }
}

use std::ffi::{c_char, CString};

unsafe extern "C" {
    fn strlen(s: *const c_char) -> usize;   // from the C library
}

fn c_len(text: &str) -> usize {
    let owned = CString::new(text).expect("no interior NUL byte");
    // SAFETY: owned is NUL-terminated and lives until the end of this
    // function, longer than the call; strlen only reads it.
    unsafe { strlen(owned.as_ptr()) }
}

fn main() {
    println!("{}", c_len("hello"));                      // 5

    let raw = CString::new("handoff").unwrap().into_raw(); // ownership to C
    // ... C code may read raw here, but must not free() it ...
    let back = unsafe { CString::from_raw(raw) };          // ownership back
    println!("{:?}", back);                                // "handoff"
}                                                          // back dropped, freed by Rust

#include <stddef.h>

typedef struct ring ring;                 /* opaque: fields hidden from users */

ring *rb_new(size_t cap);                 /* NULL if out of memory */
int   rb_push(ring *rb, int value);       /* 0 ok, -1 full */
int   rb_pop(ring *rb, int *out);         /* 0 ok, -1 empty */
void  rb_for_each(const ring *rb, void (*cb)(int value, void *user), void *user);
void  rb_free(ring *rb);

use std::{env, path::PathBuf};

fn main() {
    // 1. Compile the C file into libring.a and tell rustc to link it.
    cc::Build::new().file("csrc/ring.c").compile("ring");

    // 2. Generate Rust declarations from the header.
    let bindings = bindgen::Builder::default()
        .header("csrc/ring.h")
        .allowlist_function("rb_.*")
        .generate()
        .expect("bindgen failed");
    let out = PathBuf::from(env::var("OUT_DIR").unwrap());
    bindings.write_to_file(out.join("bindings.rs")).unwrap();

    // 3. Rerun only when the C side changes.
    println!("cargo::rerun-if-changed=csrc/ring.c");
    println!("cargo::rerun-if-changed=csrc/ring.h");
}

