pub struct Ring(NonNull<ffi::ring>); // owns the C object

impl Ring {
    pub fn new(cap: usize) -> Option<Ring> {
        // SAFETY: rb_new has no preconditions; it returns NULL on failure.
        NonNull::new(unsafe { ffi::rb_new(cap) }).map(Ring)
    }
    pub fn push(&mut self, v: i32) -> Result<(), i32> {
        // SAFETY: self.0 is a live ring from rb_new, not yet freed.
        if unsafe { ffi::rb_push(self.0.as_ptr(), v) } == 0 { Ok(()) } else { Err(v) }
    }
