impl Drop for Ring {
    fn drop(&mut self) {
        // SAFETY: we own the ring and free it exactly once.
        unsafe { ffi::rb_free(self.0.as_ptr()) }
    }
}

pub fn for_each<F: FnMut(i32)>(&self, f: F) {
    struct Ctx<F> { f: F, panic: Option<Box<dyn Any + Send>> }

    unsafe extern "C" fn trampoline<F: FnMut(i32)>(v: c_int, user: *mut c_void) {
        // SAFETY: user is the &mut Ctx<F> passed below, alive during the call.
        let ctx = unsafe { &mut *(user as *mut Ctx<F>) };
        if ctx.panic.is_some() { return; }        // skip the rest after a panic
        if let Err(p) = catch_unwind(AssertUnwindSafe(|| (ctx.f)(v))) {
            ctx.panic = Some(p);                  // never unwind into C
        }
    }

    let mut ctx = Ctx { f, panic: None };
    // SAFETY: live ring; &mut ctx outlives the call and C keeps no copy.
    unsafe {
        ffi::rb_for_each(self.0.as_ptr(), Some(trampoline::<F>),
                         &mut ctx as *mut Ctx<F> as *mut c_void);
    }
    if let Some(p) = ctx.panic { resume_unwind(p); } // C frames are gone now
}

